from pydantic import BaseModel, Field


class JobDescriptionSchema(BaseModel):
    """Structured job description generated by the LLM."""

    title: str = Field(description="The formal job title")
    overview: str = Field(description="A compelling summary of the role, team, and company mission")
    responsibilities: list[str] = Field(description="Key duties and day-to-day responsibilities")
    required_qualifications: list[str] = Field(description="Must-have skills, experience, and educational background")
    preferred_qualifications: list[str] = Field(default_factory=list, description="Nice-to-have qualifications and bonus experience")
    benefits: list[str] = Field(default_factory=list, description="Compensation, perks, health, and wellness benefits")

    def to_markdown(self) -> str:
        """Render the structured schema into a publication-ready markdown string."""
        lines = [f"# {self.title}", "", "## Overview", self.overview, "", "## Key Responsibilities"]
        for item in self.responsibilities:
            lines.append(f"- {item}")
        lines.extend(["", "## Required Qualifications"])
        for item in self.required_qualifications:
            lines.append(f"- {item}")
        if self.preferred_qualifications:
            lines.extend(["", "## Preferred Qualifications"])
            for item in self.preferred_qualifications:
                lines.append(f"- {item}")
        if self.benefits:
            lines.extend(["", "## What We Offer"])
            for item in self.benefits:
                lines.append(f"- {item}")
        return "\n".join(lines)
